#!/usr/bin/env node
// ════════════════════════════════════════════════════════════════════
// Fails if `apps/web/public/` holds a file that is not a known dev-only
// artifact, or if a dev-only artifact reached a production build.
//
// WHY THIS EXISTS
//
// `apps/web/public/` held one file, `mockServiceWorker.js`, generated by
// `msw init` and committed. Vite copies `publicDir` into the build verbatim,
// so every production build of the web app emitted
// `dist/mockServiceWorker.js`: a same-origin service worker, in production,
// which anything that calls
//
//     navigator.serviceWorker.register('/mockServiceWorker.js')
//
// installs — after which it intercepts every request from that origin and
// answers from MSW's handler list, persistently, across reloads, until
// something unregisters it. CodeQL's first run on this repository also
// flagged its `message` handler for acting on postMessage data without an
// origin check (`js/missing-origin-check`), which is the smaller half.
//
// What makes this worth a script rather than a one-line fix is *why* it was
// invisible. `apps/web/src/test/browser.ts` has a section headed "It is never
// in the production bundle", and that section is correct: `main.tsx` reaches
// MSW through a dynamic `import()` behind `import.meta.env.DEV`, which
// constant-folds to `false`, so Rollup drops the branch and the chunk.
// Measured — the production bundle contains no `msw`, `setupWorker`,
// `onUnhandledRequest` or `@flux/mocks`. The reasoning was sound and the
// verification was real.
//
// The worker *script* is not in the module graph at all. Tree-shaking is a
// property of imports, and a static asset has none, so the mechanism everyone
// trusted had nothing to say about the one file that mattered. That is the
// blind-spot shape CLAUDE.md describes: a check that covers nine cases and is
// silent, rather than wrong, about the tenth.
//
// `vite.config.ts` now sets `copyPublicDir: false`. That is blunt — the next
// person to drop a `favicon.ico` into `public/` would find it silently absent
// from the build, which trades one silent failure for another. Rule A below is
// what makes that loud instead.
//
// WHAT THIS DOES NOT CHECK
//
// Named, because a check that passes over a blind spot licenses the belief
// that the tree is clean — see CLAUDE.md.
//
//   • **Whether a dev-only asset is still needed.** If MSW is dropped, the
//     allowlist keeps asserting the worker belongs here. Stale-allowlist
//     drift, caught only by reading.
//   • **Other apps.** `apps/marketing` does not exist yet. When it does, and
//     if it has a `publicDir` that legitimately ships, it needs its own entry
//     here rather than an exemption — the point is per-directory intent, not a
//     global ban.
//   • **Assets referenced from `index.html` by path.** Those are build inputs
//     Vite rewrites, not `publicDir` copies, and this says nothing about them.
//   • Rule B is skipped when no `dist/` exists, so CI's static job (which does
//     not build the web app) reports on Rule A alone.
//
// NEGATIVE-TESTED
//
//   • `touch apps/web/public/favicon.ico` → Rule A fails, naming the file and
//     both ways forward. Nothing else in CI notices.
//   • Restoring `copyPublicDir: true` and rebuilding → Rule B fails on
//     `dist/mockServiceWorker.js`. Rule A stays green, which is the case that
//     matters: the source tree is untouched and correct, and the leak is
//     entirely in the build configuration.
// ════════════════════════════════════════════════════════════════════

import { existsSync, readdirSync, statSync } from 'node:fs'
import { join, relative } from 'node:path'
import process from 'node:process'

/**
 * Directories Vite would copy verbatim, and the files in each that are known
 * to be dev-only — generated tooling artifacts that must never ship.
 *
 * A file listed here is asserted *absent* from the build. A file not listed is
 * asserted absent from the directory, because the app it belongs to has
 * `copyPublicDir: false` and would drop it without a word.
 */
const PUBLIC_DIRS = [
  {
    dir: 'apps/web/public',
    dist: 'apps/web/dist',
    // `msw init` writes this and records the path in apps/web/package.json
    // (`msw.workerDirectory`), which is what lets MSW warn when the committed
    // copy falls behind the installed version. Moving it would break that
    // check for no gain, so it stays here and stays out of the build.
    devOnly: ['mockServiceWorker.js'],
  },
]

/** Every file under `dir`, relative to it, recursively. */
function filesUnder(dir) {
  const out = []
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    const full = join(dir, entry.name)
    if (entry.isDirectory()) out.push(...filesUnder(full).map((f) => join(entry.name, f)))
    else out.push(entry.name)
  }
  return out
}

const failures = []
let checkedDirs = 0
let checkedDists = 0

for (const { dir, dist, devOnly } of PUBLIC_DIRS) {
  if (!existsSync(dir)) continue
  checkedDirs += 1

  // ── Rule A — nothing in publicDir but the known dev-only artifacts ──
  const present = filesUnder(dir).sort()
  const unexpected = present.filter((f) => !devOnly.includes(f))
  for (const file of unexpected) {
    failures.push({
      rule: 'A',
      subject: join(dir, file),
      detail: [
        `  not a known dev-only artifact, and \`copyPublicDir: false\` means it will`,
        `  NOT reach the build — silently, with no warning from Vite.`,
        ``,
        `  If it must ship: reference it from source (\`import url from './x.png'\`)`,
        `  or from index.html, so it becomes a build input Vite hashes and rewrites.`,
        `  If it is another dev-only artifact: add it to devOnly in this script,`,
        `  with a comment saying what generates it.`,
      ].join('\n'),
    })
  }

  // ── Rule B — no dev-only artifact reached the build ─────────────────
  if (!existsSync(dist)) continue
  checkedDists += 1
  for (const file of devOnly) {
    const shipped = join(dist, file)
    if (!existsSync(shipped)) continue
    failures.push({
      rule: 'B',
      subject: shipped,
      detail: [
        `  a dev-only artifact reached the production build (${statSync(shipped).size} bytes).`,
        ``,
        `  \`copyPublicDir: false\` in ${join(relative('.', dir), '..')}/vite.config.ts is what`,
        `  keeps ${file} out of dist/. If that was turned back on, the`,
        `  comment above it says why it is off; if dist/ is simply stale, rebuild.`,
        ``,
        `  For mockServiceWorker.js specifically this is not cosmetic: a service`,
        `  worker served from the app's own origin can be registered by any script`,
        `  on it, and then answers every request the page makes.`,
      ].join('\n'),
    })
  }
}

if (checkedDirs === 0) {
  console.log('No publicDir found for any app — nothing to check.')
} else {
  console.log(
    `Checked ${checkedDirs} publicDir(s) and ${checkedDists} build output(s): ` +
      PUBLIC_DIRS.map(({ dir }) => dir).join(', '),
  )
}

if (failures.length > 0) {
  console.error('')
  for (const failure of failures) {
    console.error(`  ✗ [Rule ${failure.rule}] ${failure.subject}`)
    console.error(failure.detail)
    console.error('')
  }
  console.error('  A dev-only asset in a production build is not dead weight, it is a')
  console.error('  surface. The header has the full account of how one shipped.')
  console.error('')
  process.exit(1)
}

console.log('✓ publicDir holds only known dev-only artifacts, and none of them shipped.')
